1. Initialize a variable "isPrime" to true.
2. If the number is less than 2, set "isPrime" to false.
3. Loop through all integers from 2 to the square root of the number.
4. If the number is divisible by any of these integers, set "isPrime" to false and break out of the loop.
5. Return the value of "isPrime". 

In code:

```
function isPrime(num) {
  let isPrime = true;
  if (num < 2) {
    isPrime = false;
    return isPrime;
  }
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      isPrime = false;
      break;
    }
  }
  return isPrime;
}

console.log(isPrime(7)); // Output: true
```

