Here's a C++ program that implements Dijkstra's algorithm to find the shortest path between two nodes in a graph represented by an adjacency matrix:
```c++
#include <iostream>
#include <vector>
#include <queue>
#include <climits>
using namespace std;
// Function to find the shortest path between two nodes using Dijkstra's algorithm
void dijkstra(vector<vector<int>>& graph, int start, int end) {
    int n = graph.size();
    vector<int> dist(n, INT_MAX); // Initialize distances to all nodes as infinity
    vector<int> prev(n, -1); // Initialize previous node for each node as -1
    vector<bool> visited(n, false); // Initialize all nodes as unvisited
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq; // Create a priority queue to store nodes with their distances from start node
    dist[start] = 0; // Distance from start node to itself is 0
    pq.push(make_pair(0, start)); // Push start node into priority queue with distance 0
    while (!pq.empty()) {
        int u = pq.top().second; // Get the node with minimum distance from start node
        pq.pop();
        if (visited[u]) {
            continue; // If the node has already been visited, skip it
        }
        visited[u] = true; // Mark the node as visited
        for (int v = 0; v < n; v++) {
            if (graph[u][v] != 0) { // If there is an edge between u and v
                int alt = dist[u] + graph[u][v]; // Calculate the distance from start node to v through u
                if (alt < dist[v]) { // If the calculated distance is less than the previously recorded distance
                    dist[v] = alt; // Update the distance to v
                    prev[v] = u; // Update the previous node for v
                    pq.push(make_pair(dist[v], v)); // Push v into priority queue with updated distance
                }
            }
        }
    }
    // Output the shortest distance and the path taken
    cout << "Shortest distance from node " << start << " to node " << end << " is " << dist[end] << endl;
    cout << "Path taken: ";
    int u = end;
    while (u != -1) {
        cout << u << " ";
        u = prev[u];
    }
    cout << endl;
}
int main() {
    int n;
    cin >> n;
    vector<vector<int>> graph(n, vector<int>(n, 0)); // Initialize adjacency matrix with zeros
    // Input the adjacency matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> graph[i][j];
        }
    }
    int start, end;
    cin >> start >> end;
    dijkstra(graph, start, end);
    return 0;
}
```
The program first inputs the number of nodes and the adjacency matrix. It then inputs the start and end nodes. It calls the `dijkstra` function to find the shortest path between the start and end nodes using Dijkstra's algorithm. The `dijkstra` function initializes the distances to all nodes as infinity, the previous node for each node as -1, and all nodes as unvisited. It creates a priority queue to store nodes with their distances from the start node. It pushes the start node into the priority queue with distance 0. It then loops through the priority queue until it is empty. In each iteration, it gets the node with minimum distance from the start node and marks it as visited. It then loops through all the neighbors of the current node and calculates the distance from the start node to the neighbor through the current node. If the calculated distance is less than the previously recorded distance, it updates the distance to the neighbor, the previous node for the neighbor, and pushes the neighbor into the priority queue with the updated distance. Once the priority queue is empty, the function outputs the shortest distance and the path taken.
