double sigmoid(double x) {
    return 1 / (1 + exp(-x));
}
// Define the derivative of the sigmoid function
double sigmoid_derivative(double x) {
    return sigmoid(x) * (1 - sigmoid(x));
}
// Define the neural network class
class NeuralNetwork {
public:
    NeuralNetwork(vector<int> sizes) {
        // Initialize the weights and biases randomly
        for (int i = 1; i < sizes.size(); i++) {
            weights.push_back(vector<double>(sizes[i], 0));
            biases.push_back(vector<double>(sizes[i], 0));
            for (int j = 0; j < sizes[i]; j++) {
                for (int k = 0; k < sizes[i-1]; k++) {
                    weights[i-1][j] += (double)rand() / RAND_MAX - 0.5;
                }
                biases[i-1][j] = (double)rand() / RAND_MAX - 0.5;
            }
        }
    }
    // Define the feedforward function
    vector<double> feedforward(vector<double> input) {
        for (int i = 0; i < weights.size(); i++) {
            vector<double> output(weights[i].size(), 0);
            for (int j = 0; j < weights[i].size(); j++) {
                for (int k = 0; k < input.size(); k++) {
                    output[j] += weights[i][j][k] * input[k];
                }
                output[j] += biases[i][j];
                output[j] = sigmoid(output[j]);
            }
            input = output;
        }
        return input;
    }
    // Define the backpropagation function
    void backpropagation(vector<double> input, vector<double> target, double learning_rate) {
        vector<vector<double>> activations;
        vector<vector<double>> outputs;
        activations.push_back(input);
        vector<double> output = input;
        for (int i = 0; i < weights.size(); i++) {
            vector<double> activation(output.size(), 0);
            for (int j = 0; j < output.size(); j++) {
                activation[j] = sigmoid_derivative(output[j]);
            }
            activations.push_back(activation);
            outputs.push_back(output);
            output = vector<double>(weights[i].size(), 0);
            for (int j = 0; j < weights[i].size(); j++) {
                for (int k = 0; k < outputs[i].size(); k++) {
                    output[j] += weights[i][j][k] * outputs[i][k];
                }
                output[j] += biases[i][j];
                output[j] = sigmoid(output[j]);
            }
        }
        vector<double> error = vector<double>(target.size(), 0);
        for (int i = 0; i < target.size(); i++) {
            error[i] = target[i] - output[i];
        }
        for (int i = weights.size() - 1; i >= 0; i--) {
            vector<double> delta(weights[i].size(), 0);
            for (int j = 0; j < weights[i].size(); j++) {
                double error_sum = 0;
                for (int k = 0; k < weights[i+1].size(); k++) {
                    error_sum += delta[k] * weights[i+1][k][j];
                }
                delta[j] = error_sum * activations[i+1][j];
                for (int k = 0; k < weights[i][j].size(); k++) {
                    weights[i][j][k] += learning_rate * delta[j] * outputs[i][k];
                }
                biases[i][j] += learning_rate * delta[j];
            }
        }
    }
private:
    vector<vector<vector<double>>> weights;
    vector<vector<double>> biases;
};
int main() {
    // Define the neural network architecture
    vector<int> sizes = {2, 3, 1};
    NeuralNetwork nn(sizes);
    // Train the neural network on the XOR function
    for (int i = 0; i < 10000; i++) {
        vector<double> input = {0, 0};
        vector<double> target = {0};
        nn.backpropagation(input, target, 0.1);
        input = {0, 1};
        target = {1};
