    cout << "0 XOR 1 = " << output[0] << endl;
    input = {1, 0};
    output = nn.feedforward(input);
    cout << "1 XOR 0 = " << output[0] << endl;
    input = {1, 1};
    output = nn.feedforward(input);
    cout << "1 XOR 1 = " << output[0] << endl;
    return 0;
}
```
