func sortBooksByYearAndAddISBN(books: [Book], apiKey: String) -> [Book] {
    var booksWithISBN: [Book] = []
    var remainingBooks: [Book] = books

    while remainingBooks.count > 0 {
        let batchSize = min(remainingBooks.count, 10)
        let batch = Array(remainingBooks.prefix(batchSize))
        remainingBooks.removeFirst(batchSize)

        let titles = batch.map { $0.title }
        let authors = batch.map { $0.author }

        let url = URL(string: "https://api.example.com/books?title=\(titles.joined(separator: ","))&author=\(authors.joined(separator: ","))&apiKey=\(apiKey)")!
        let data = try! Data(contentsOf: url)
        let response = try! JSONSerialization.jsonObject(with: data) as! [String: String]

        for book in batch {
            if let isbn = response["\(book.title)-\(book.author)"] {
                var bookWithISBN = book
                bookWithISBN.isbn = isbn
                booksWithISBN.append(bookWithISBN)
            }
        }
    }

    return booksWithISBN.sorted { $0.year < $1.year }
}
```
