int countSubstring(const string& haystack, const string& needle, bool caseSensitive = true, bool useRegex = false, size_t startPos = 0) {
    if (haystack.empty() || needle.empty()) {
        cerr << "Error: input strings cannot be empty!" << endl;
        return -1;
    }
    if (startPos >= haystack.length()) {
        cerr << "Error: starting position is out of range!" << endl;
        return -1;
    }
    if (!caseSensitive) {
        transform(haystack.begin(), haystack.end(), haystack.begin(), ::tolower);
        transform(needle.begin(), needle.end(), needle.begin(), ::tolower);
    }
    int count = 0;
    string::const_iterator it = haystack.begin() + startPos;
    if (useRegex) {
        regex pattern(needle);
        smatch match;
        while (regex_search(it, haystack.cend(), match, pattern)) {
            count++;
            it = match.suffix().first;
