    prev = head
    curr = head.next
    seen = set([head.val])

    while curr:
        if curr.val in seen:
            prev.next = curr.next
        else:
            seen.add(curr.val)
            prev = curr
        curr = curr.next

    return head
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True
def filter_primes(head):
    if not head:
        return None

    curr = head
    primes = []

    while curr:
        if is_prime(curr.val):
            primes.append(curr.val)
        curr = curr.next

    primes.sort(reverse=True)

    new_head = Node(primes[0])
    curr = new_head

    for i in range(1, len(primes)):
        curr.next = Node(primes[i])
        curr = curr.next

    return new_head
