```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <wn.h>
std::string find_antonym(const std::string& word) {
    wninit();
    SynsetPtr synset = findtheinfo_ds(word.c_str(), NOUN, HYPERPTR, 1);
    if (!synset) {
        return "";
    }
    std::vector<PointerType> pointers;
    getptrs(synset, &pointers);
    std::string antonym;
    for (const auto& pointer : pointers) {
        if (pointer->pt_type == ANTPTR) {
            SynsetPtr target_synset = read_synset(pointer->target);
            if (target_synset) {
                for (int i = 0; i < target_synset->wcount; ++i) {
                    if (target_synset->words[i]) {
                        antonym = target_synset->words[i];
                        break;
                    }
                }
            }
        }
    }
    return antonym;
}
