GridSearchCV and RandomizedSearchCV are two popular techniques for hyperparameter tuning in machine learning. They both aim to find the optimal hyperparameters for a given model by searching through a defined space of possible values.
In C#, you can use the ML.NET library to implement GridSearchCV and RandomizedSearchCV for hyperparameter tuning. The ML.NET library provides a GridSearchCV and a RandomizedSearchCV class that you can use to perform hyperparameter tuning.
To ensure that the selected techniques are both efficient and effective, it is important to define a reasonable search space for the hyperparameters and to set appropriate values for the search parameters such as the number of iterations and the cross-validation folds.
Here is an example of how to use GridSearchCV and RandomizedSearchCV in a machine learning model:
```csharp
using System;
using System.Linq;
using Microsoft.ML;
using Microsoft.ML.Data;
using Microsoft.ML.Trainers;
using Microsoft.ML.Transforms;
namespace HyperparameterTuning
{
    class Program
    {
        static void Main(string[] args)
        {
            // Load the data
            var mlContext = new MLContext();
            var data = mlContext.Data.LoadFromTextFile<IrisData>("iris.data", separatorChar: ',');
            // Define the pipeline
            var pipeline = mlContext.Transforms.Conversion.MapValueToKey("Label")
                .Append(mlContext.Transforms.Concatenate("Features", "SepalLength", "SepalWidth", "PetalLength", "PetalWidth"))
                .Append(mlContext.Transforms.NormalizeMinMax("Features"))
                .Append(mlContext.Transforms.Conversion.MapKeyToValue("Label"))
                .Append(mlContext.Transforms.Splitter.TrainTestSplit(testFraction: 0.3))
                .Append(mlContext.Transforms.Conversion.MapKeyToValue("Label"));
            // Define the estimator
            var estimator = mlContext.Transforms.Conversion.MapValueToKey("Label")
                .Append(mlContext.Transforms.Concatenate("Features", "SepalLength", "SepalWidth", "PetalLength", "PetalWidth"))
                .Append(mlContext.Transforms.NormalizeMinMax("Features"))
                .Append(mlContext.Transforms.Conversion.MapKeyToValue("Label"))
                .Append(mlContext.Transforms.Splitter.TrainTestSplit(testFraction: 0.3))
                .Append(mlContext.Transforms.Conversion.MapKeyToValue("Label"))
                .Append(mlContext.Transforms.Concatenate("Features"))
                .Append(mlContext.Transforms.NormalizeMinMax("Features"))
                .Append(mlContext.Transforms.Conversion.MapValueToKey("Label"))
                .Append(mlContext.Transforms.Trainers.SdcaNonCalibrated(new SdcaNonCalibratedTrainer.Options
                {
                    MaximumNumberOfIterations = 100,
                    L2Regularization = 0.1f
                }))
                .Append(mlContext.Transforms.Conversion.MapKeyToValue("Label"));
            // Define the hyperparameters to tune
            var hyperparameters = new GridSearchParameterSet
            {
                { "Trainers.SdcaNonCalibrated.MaximumNumberOfIterations", new[] { 50, 100, 200 } },
                { "Trainers.SdcaNonCalibrated.L2Regularization", new[] { 0.1f, 0.01f, 0.001f } }
            };
            // Define the search parameters
            var searchParameters = new GridSearchParameters
            {
                MaxIterations = 10,
                ParameterSet = hyperparameters,
                RunParallel = true
            };
            // Perform grid search cross-validation
            var cvResults = mlContext.Auto().Fit(data).CrossValidateEstimator(estimator, searchParameters);
            // Print the results
            Console.WriteLine($"Grid search cross-validation results:");
            Console.WriteLine($"  Best score: {cvResults.BestScore:F3}");
            Console.WriteLine($"  Best hyperparameters: {string.Join(", ", cvResults.BestParameters.Select(p => $"{p.Key}={p.Value}"))}");
            Console.WriteLine($"  All scores: {string.Join(", ", cvResults.AllScores.Select(s => $"{s:F3}"))}");
            // Define the hyperparameters to tune
            var hyperparameters2 = new RandomSearchParameterSet
            {
                { "Trainers.SdcaNonCalibrated.MaximumNumberOfIterations", new RandomSearchParameter<int>(50, 200) },
                { "Trainers.SdcaNonCalibrated.L2Regularization", new RandomSearchParameter<float>(0.001f, 0.1f) }
            };
            // Define the search parameters
            var searchParameters2 = new RandomSearchParameters
            {
                MaxIterations = 10,
                ParameterSet = hyperparameters2,
                RunParallel = true
            };
            // Perform random search cross-validation
            var cvResults2 = mlContext.Auto().Fit(data).CrossValidateEstimator(estimator, searchParameters2);
            // Print the results
            Console.WriteLine($"Random search cross-validation results:");
            Console.WriteLine($"  Best score: {cvResults2.BestScore:F3}");
            Console.WriteLine($"  Best hyperparameters: {string.Join(", ", cvResults2.BestParameters.Select(p => $"{p.Key}={p.Value}"))}");
            Console.WriteLine($"  All scores: {string.Join(", ", cvResults2.AllScores.Select(s => $"{s:F3}"))}");
        }
    }
