Here's a sample code to perform sentiment analysis using the Naive Bayes algorithm in Go:
```
package main
import (
    "bufio"
    "fmt"
    "io/ioutil"
    "log"
    "math"
    "os"
    "path/filepath"
    "regexp"
    "strings"
)
type NaiveBayes struct {
    WordCount map[string]float64
    TotalWordCount float64
    ClassCount map[string]float64
    Vocabulary map[string]bool
}
func (nb *NaiveBayes) Train(class string, text string) {
    nb.ClassCount[class] += 1.0
    words := tokenize(text)
    for _, word := range words {
        nb.WordCount[class + word] += 1.0
        nb.Vocabulary[word] = true
        nb.TotalWordCount += 1.0
    }
}
func (nb *NaiveBayes) Predict(text string) string {
    words := tokenize(text)
    var classes []string
    for class := range nb.ClassCount {
        prob := nb.ClassCount[class] / nb.TotalWordCount
        for _, word := range words {
            prob *= nb.WordProb(class, word)
        }
        classes = append(classes, class)
    }
    return argmax(classes, func(c string) float64 {
        prob := nb.ClassCount[c] / nb.TotalWordCount
        for _, word := range words {
            prob *= nb.WordProb(c, word)
        }
        return prob
    })
}
func (nb *NaiveBayes) WordProb(class string, word string) float64 {
    count := nb.WordCount[class + word]
    total := nb.ClassCount[class] + nb.TotalWordCount
    return (count + 1.0) / total
}
func tokenize(text string) []string {
    text = strings.ToLower(text)
    re := regexp.MustCompile("\\w+")
    words := re.FindAllString(text, -1)
    return words
}
func argmax(slice []string, f func(string) float64) string {
    var maxVal float64 = math.Inf(-1)
    var maxArg string
    for _, val := range slice {
        if f(val) > maxVal {
            maxVal = f(val)
            maxArg = val
        }
    }
    return maxArg
}
func main() {
    nb := &NaiveBayes{
        WordCount: make(map[string]float64),
        ClassCount: make(map[string]float64),
        Vocabulary: make(map[string]bool),
    }
    // Train on positive reviews
    posFiles, err := filepath.Glob("positive/*.txt")
    if err != nil {
        log.Fatal(err)
    }
    for _, file := range posFiles {
        text, err := ioutil.ReadFile(file)
        if err != nil {
            log.Fatal(err)
        }
        nb.Train("positive", string(text))
    }
    // Train on negative reviews
    negFiles, err := filepath.Glob("negative/*.txt")
    if err != nil {
        log.Fatal(err)
    }
    for _, file := range negFiles {
        text, err := ioutil.ReadFile(file)
        if err != nil {
            log.Fatal(err)
        }
        nb.Train("negative", string(text))
    }
    // Classify some test data
    testFiles, err := filepath.Glob("test/*.txt")
    if err != nil {
        log.Fatal(err)
    }
    for _, file := range testFiles {
        text, err := ioutil.ReadFile(file)
        if err != nil {
            log.Fatal(err)
        }
        class := nb.Predict(string(text))
        fmt.Printf("%s: %s\n", file, class)
    }
}
```
