var dataProcessingPipeline = mlContext.Transforms.Text.FeaturizeText("Features", nameof(SocialMediaData.Text))
    .Append(mlContext.Transforms.Conversion.MapValueToKey(nameof(SocialMediaData.Sentiment)))
    .Append(mlContext.Transforms.NormalizeMinMax(nameof(SocialMediaData.Features)));
// Define the training algorithm
var trainingPipeline = dataProcessingPipeline
    .Append(mlContext.Transforms.Conversion.MapKeyToValue(nameof(SocialMediaData.Sentiment)))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression());
// Train the model
var trainedModel = trainingPipeline.Fit(trainTestSplit.TrainSet);
// Evaluate the model
