```
double CalculateFraminghamRiskScore(int age, int systolicBloodPressure, bool isTakingMedicationForBP, int totalCholesterol, int hdlCholesterol, bool isSmoker, bool isDiabetic, bool isMale)
{
    double riskScore = 0.0;
    // Calculate age factor
    if (age >= 30 && age <= 34)
    {
        riskScore += isMale ? -9.3 : -7.5;
    }
    else if (age >= 35 && age <= 39)
    {
        riskScore += isMale ? -4.2 : -3.1;
    }
    else if (age >= 40 && age <= 44)
