        riskScore += isMale ? 0.0 : 0.0;
    }
    else if (age >= 45 && age <= 49)
    {
        riskScore += isMale ? 3.1 : 2.3;
    }
    else if (age >= 50 && age <= 54)
    {
        riskScore += isMale ? 6.6 : 4.5;
    }
    else if (age >= 55 && age <= 59)
    {
        riskScore += isMale ? 8.2 : 6.7;
    }
    else if (age >= 60 && age <= 64)
    {
        riskScore += isMale ? 9.8 : 9.2;
    }
    else if (age >= 65 && age <= 69)
    {
        riskScore += isMale ? 12.4 : 12.0;
    }
    else if (age >= 70 && age <= 74)
    {
        riskScore += isMale ? 14.8 : 14.8;
    }
    else if (age >= 75 && age <= 79)
    {
        riskScore += isMale ? 17.5 : 19.3;
    }
    // Calculate blood pressure factor
    if (systolicBloodPressure < 120)
    {
        riskScore += 0.0;
    }
    else if (systolicBloodPressure >= 120 && systolicBloodPressure <= 129)
    {
        riskScore += isTakingMedicationForBP ? 0.0 : 0.0;
    }
    else if (systolicBloodPressure >= 130 && systolicBloodPressure <= 139)
    {
        riskScore += isTakingMedicationForBP ? 1.0 : 0.0;
    }
    else if (systolicBloodPressure >= 140 && systolicBloodPressure <= 149)
    {
        riskScore += isTakingMedicationForBP ? 2.0 : 1.0;
    }
    else if (systolicBloodPressure >= 150 && systolicBloodPressure <= 159)
    {
        riskScore += isTakingMedicationForBP ? 2.0 : 1.5;
    }
    else if (systolicBloodPressure >= 160)
    {
        riskScore += isTakingMedicationForBP ? 3.0 : 2.0;
    }
    // Calculate cholesterol factor
    double ldlCholesterol = totalCholesterol - hdlCholesterol - 38;
    if (ldlCholesterol < 0)
    {
        ldlCholesterol = totalCholesterol - hdlCholesterol;
    }
    if (ldlCholesterol < 100)
    {
        riskScore += 0.0;
    }
    else if (ldlCholesterol >= 100 && ldlCholesterol <= 129)
    {
        riskScore += 0.0;
    }
    else if (ldlCholesterol >= 130 && ldlCholesterol <= 159)
    {
        riskScore += 1.0;
    }
    else if (ldlCholesterol >= 160 && ldlCholesterol <= 189)
    {
        riskScore += 2.0;
    }
    else if (ldlCholesterol >= 190)
    {
        riskScore += 3.0;
    }
    // Calculate smoking and diabetes factors
    if (isSmoker)
    {
        riskScore += 4.0;
    }
    if (isDiabetic)
    {
        riskScore += 4.0;
    }
    return riskScore;
}
