Here is some sample code to get started with creating a game using C#:
```
using System;
using System.Drawing;
using System.Windows.Forms;
public class ReindeerGame : Form
{
   private PictureBox player;
   private PictureBox present;
   private PictureBox obstacle;
   private Timer timer;
   private int score;
   public ReindeerGame()
   {
      this.Text = "Reindeer Game";
      this.ClientSize = new Size(600, 400);
      this.KeyDown += new KeyEventHandler(ReindeerMove);
      this.timer = new Timer();
      this.timer.Interval = 1000;
      this.timer.Tick += new EventHandler(GameLoop);
      this.timer.Start();
      this.score = 0;
      this.player = new PictureBox();
      this.player.Image = Image.FromFile("reindeer.png");
      this.player.SizeMode = PictureBoxSizeMode.StretchImage;
      this.player.Size = new Size(50, 50);
      this.player.Location = new Point(50, 200);
      this.Controls.Add(player);
      this.present = new PictureBox();
      this.present.Image = Image.FromFile("present.png");
      this.present.SizeMode = PictureBoxSizeMode.StretchImage;
      this.present.Size = new Size(50, 50);
      this.present.Location = new Point(500, 100);
      this.Controls.Add(present);
      this.obstacle = new PictureBox();
      this.obstacle.Image = Image.FromFile("obstacle.png");
      this.obstacle.SizeMode = PictureBoxSizeMode.StretchImage;
      this.obstacle.Size = new Size(50, 50);
      this.obstacle.Location = new Point(500, 300);
      this.Controls.Add(obstacle);
   }
   private void ReindeerMove(object sender, KeyEventArgs e)
   {
      if (e.KeyCode == Keys.Up)
      {
         player.Top -= 10;
      }
      else if (e.KeyCode == Keys.Down)
      {
         player.Top += 10;
      }
   }
   private void GameLoop(object sender, EventArgs e)
   {
      present.Left -= 5;
      obstacle.Left -= 5;
      if (present.Left < -50)
      {
         present.Left = 600;
         present.Top = new Random().Next(50, 350);
      }
      if (obstacle.Left < -50)
      {
         obstacle.Left = 600;
         obstacle.Top = new Random().Next(50, 350);
      }
      if (player.Bounds.IntersectsWith(present.Bounds))
      {
         score += 10;
         present.Left = 600;
         present.Top = new Random().Next(50, 350);
      }
      if (player.Bounds.IntersectsWith(obstacle.Bounds))
      {
         timer.Stop();
         MessageBox.Show("Game Over! Your score was: " + score);
         Application.Exit();
      }
   }
   public static void Main()
   {
      Application.Run(new ReindeerGame());
   }
}
```
