```
% Load the NLTK library
javaaddpath('path/to/nltk.jar');
import edu.stanford.nlp.*;
% Load the sentences from the Excel file
sentences = readtable('path/to/excel/file.xlsx', 'Sheet', 'Sheet1', 'Range', 'A2:A4');
sentences = table2cell(sentences);
% Initialize the StanfordCoreNLP pipeline
props = java.util.Properties();
props.setProperty('annotators', 'tokenize, ssplit, pos, lemma, parse');
pipeline = javaObject('edu.stanford.nlp.pipeline.StanfordCoreNLP', props);
% Loop through each sentence and extract the verb and its tense
for i = 1:length(sentences)
    % Apply the StanfordCoreNLP pipeline to the sentence
    annotation = javaObject('edu.stanford.nlp.pipeline.Annotation', sentences{i});
    pipeline.annotate(annotation);
    sentencesAnnotated = annotation.get(javaObject('edu.stanford.nlp.util.CoreAnnotations$SentencesAnnotation'));
    sentence = sentencesAnnotated.get(0);
    tokens = sentence.get(javaObject('edu.stanford.nlp.util.CoreAnnotations$TokensAnnotation'));

    % Loop through each token and find the verb and its tense
    verb = '';
    tense = '';
    for j = 1:length(tokens)
        token = tokens.get(j-1);
        posTag = token.get(javaObject('edu.stanford.nlp.ling.CoreAnnotations$PartOfSpeechAnnotation'));
        lemma = token.get(javaObject('edu.stanford.nlp.ling.CoreAnnotations$LemmaAnnotation'));
        if strcmp(posTag, 'VB') || strcmp(posTag, 'VBD') || strcmp(posTag, 'VBG') || strcmp(posTag, 'VBN') || strcmp(posTag, 'VBP') || strcmp(posTag, 'VBZ')
            verb = lemma;
            tense = getTense(posTag);
            break;
        end
    end

    % Print the verb and its tense
    fprintf('Sentence %d: %s (%s)\n', i, verb, tense);
end
% Function to get the tense of a verb based on its POS tag
function tense = getTense(posTag)
    if strcmp(posTag, 'VBD') || strcmp(posTag, 'VBN')
        tense = 'past tense';
    elseif strcmp(posTag, 'VBZ') || strcmp(posTag, 'VBP')
        tense = 'present tense';
    elseif strcmp(posTag, 'VBG')
        tense = 'present participle';
    else
        tense = 'infinitive';
    end
end
```
Make sure to replace `path/to/nltk.jar` and `path/to/excel/file.xlsx` with the actual paths to the NLTK library and the Excel file, respectively. 
The code reads the sentences from the Excel file and applies the StanfordCoreNLP pipeline to each sentence to extract the verb and its tense. The `getTense` function determines the tense of the verb based on its POS tag. The output is printed to the console.

