public static int hexToDecimal(String hex) {
    int decimal = 0;
    int power = 0;
    for (int i = hex.length() - 1; i >= 0; i--) {
        char c = hex.charAt(i);
        int digit = Character.isDigit(c) ? c - '0' : c - 'A' + 10;
        decimal += digit * Math.pow(16, power);
        power++;
    }
    return decimal;
}
