Yes, it is possible to use a shell command in C++ to find the determinant of a 5x5 matrix. One way to do this is to use the "awk" command to perform the calculation.
Here is an example code that reads in a 5x5 matrix from standard input and outputs its determinant:
```c++
#include <iostream>
#include <cstdio>
#include <cstdlib>
#include <cstring>
using namespace std;
int main() {
    double matrix[5][5];
    int i, j;
    double det;
    // Read in the matrix from standard input
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 5; j++) {
            cin >> matrix[i][j];
        }
    }
    // Construct the awk command to calculate the determinant
    char cmd[1000];
    sprintf(cmd, "echo 'define f(%d,%d) {%f};',%d,%d; echo 'det([f]);' | awk -f /usr/bin/gawk", 5, 5, 0.0, 5, 5);
    // Open a pipe to the awk command
    FILE* pipe = popen(cmd, "w");
    // Write the matrix elements to the pipe
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 5; j++) {
            fprintf(pipe, "%f ", matrix[i][j]);
        }
        fprintf(pipe, "\n");
    }
    // Close the pipe
    pclose(pipe);
    // Read the result from standard input
    cin >> det;
    // Output the determinant
    cout << "Determinant: " << det << endl;
    return 0;
}
```
Note that this code assumes that the "gawk" command is installed at /usr/bin/gawk. If it is installed elsewhere on your system, you will need to modify the command accordingly.

