		let operator = "";
		let operand = "";
		function addToResult(value) {
			if (value === "+" || value === "-" || value === "*" || value === "/") {
				operator = value;
				operand = currentResult;
				currentResult = 0;
			} else {
				currentResult = (currentResult * 10) + parseInt(value);
			}
			resultField.value = currentResult;
		}
		function clearResult() {
			currentResult = 0;
			operator = "";
			operand = "";
			resultField.value = currentResult;
		}
		function calculateResult() {
			let result;
			switch (operator) {
				case "+":
					result = parseInt(operand) + parseInt(currentResult);
					break;
				case "-":
					result = parseInt(operand) - parseInt(currentResult);
					break;
				case "*":
					result = parseInt(operand) * parseInt(currentResult);
					break;
				case "/":
					result = parseInt(operand) / parseInt(currentResult);
					break;
				default:
