// Evaluate the arithmetic expression based on the user's input
func evaluateExpression(expression: String, order: [String]) -> Double {
    var nums: [Double] = []
    var ops: [String] = []

    // Split the expression into individual numbers and operators
    let components = expression.components(separatedBy: " ")

    // Iterate through the components and add them to the nums or ops array
    for component in components {
        if let num = Double(component) {
            nums.append(num)
        } else {
            ops.append(component)
        }
    }

    // Iterate through the order array and perform the operations in the specified order
    for op in order {
        while ops.contains(op) {
            if let index = ops.firstIndex(of: op) {
                let num1 = nums[index]
                let num2 = nums[index+1]
                let result: Double

                switch op {
                case "+":
                    result = num1 + num2
                case "-":
                    result = num1 - num2
                case "*":
                    result = num1 * num2
                case "/":
                    result = num1 / num2
                default:
                    result = 0
                }

                // Replace the two numbers and operator with the result
                nums.remove(at: index)
                nums.remove(at: index)
                nums.insert(result, at: index)
                ops.remove(at: index)
            }
        }
    }

    // Return the final result
    return nums.first!
}
