```swift
import Foundation
// Define the equation
let equation = "2x^2 + 3y - 4z^-1 = 10"
// Split the equation by the equal sign
let sides = equation.components(separatedBy: "=")
// Split each side by the plus and minus signs
let leftSide = sides[0].components(separatedBy: CharacterSet(charactersIn: "+-"))
let rightSide = sides[1].components(separatedBy: CharacterSet(charactersIn: "+-"))
// Create a dictionary to store the coefficients of each variable
var coefficients: [String: Double] = [:]
// Loop through each term on the left side of the equation
for term in leftSide {
    // Split the term into its coefficient and variable
    let parts = term.trimmingCharacters(in: .whitespacesAndNewlines).components(separatedBy: "^")
    if parts.count == 1 {
        // If the term doesn't have an exponent, assume it's x^1
        coefficients["x"] = (coefficients["x"] ?? 0) + Double(parts[0])!
    } else {
        // If the term has an exponent, use it as the variable
        coefficients[parts[1]] = (coefficients[parts[1]] ?? 0) + Double(parts[0])!
    }
}
// Loop through each term on the right side of the equation
for term in rightSide {
    // Split the term into its coefficient and variable
    let parts = term.trimmingCharacters(in: .whitespacesAndNewlines).components(separatedBy: "^")
    if parts.count == 1 {
        // If the term doesn't have an exponent, assume it's x^1
        coefficients["x"] = (coefficients["x"] ?? 0) - Double(parts[0])!
    } else {
        // If the term has an exponent, use it as the variable
        coefficients[parts[1]] = (coefficients[parts[1]] ?? 0) - Double(parts[0])!
    }
}
// Solve the equation
let x = coefficients["x"]! / coefficients.keys.filter { $0 != "x" }.reduce(1.0) { result, key in result * coefficients[key]! }
let y = coefficients["y"]! / coefficients.keys.filter { $0 != "y" }.reduce(1.0) { result, key in result * coefficients[key]! }
let z = coefficients["z"]! / coefficients.keys.filter { $0 != "z" }.reduce(1.0) { result, key in result * coefficients[key]! }
// Print the solution
print("x = \(x)")
print("y = \(y)")
print("z = \(z)")
```
