```
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;
bool is_active_voice(string sentence) {
    // Convert the sentence to lowercase
    transform(sentence.begin(), sentence.end(), sentence.begin(), ::tolower);

    // Check if the sentence contains any form of "be" followed by a verb
    if (sentence.find("am ") != string::npos ||
        sentence.find("is ") != string::npos ||
        sentence.find("are ") != string::npos ||
        sentence.find("was ") != string::npos ||
        sentence.find("were ") != string::npos) {
        size_t verb_pos = sentence.find("ed ");
        if (verb_pos == string::npos) {
            verb_pos = sentence.find("ing ");
        }
        if (verb_pos != string::npos) {
            size_t subject_pos = sentence.rfind(" ", verb_pos - 1) + 1;
            string subject = sentence.substr(subject_pos, verb_pos - subject_pos);
            if (sentence.find(subject + " " + "the ") != string::npos ||
                sentence.find(subject + " " + "a ") != string::npos ||
                sentence.find(subject + " " + "an ") != string::npos) {
                return true;
            }
        }
    }
    return false;
}
int main() {
    string sentence;
    cout << "Enter a sentence: ";
    getline(cin, sentence);

    if (is_active_voice(sentence)) {
        cout << "Active voice" << endl;
    } else {
        cout << "Passive voice" << endl;
    }

    return 0;
}
```
The `is_active_voice` function takes a string `sentence` as input and returns `true` if the sentence is in active voice, and `false` otherwise. It does this by first converting the sentence to lowercase, then checking if the sentence contains any form of "be" (i.e. "am", "is", "are", "was", or "were") followed by a verb. If it does, it then looks for the subject of the sentence (i.e. the noun that comes before the verb) and checks if it is followed by "the", "a", or "an". If it is, then the sentence is in active voice.
The `main` function prompts the user to enter a sentence, calls the `is_active_voice` function to determine if the sentence is in active voice, and then outputs the result.

