```scala
import processing.core._
object TectonicPlates extends PApplet {
  val width = 800
  val height = 600
  val plateSpeed = 0.5f
  val plateCount = 7
  val plateSize = 100
  val plateColors = Seq(
    color(255, 0, 0), // North American Plate
    color(0, 255, 0), // South American Plate
    color(0, 0, 255), // Pacific Plate
    color(255, 255, 0), // African Plate
    color(255, 0, 255), // Eurasian Plate
    color(0, 255, 255), // Australian Plate
    color(128, 128, 128) // Antarctic Plate
  )
  var plates: Seq[Plate] = Seq()
  def main(args: Array[String]) {
    PApplet.main("TectonicPlates")
  }
  override def settings(): Unit = {
    size(width, height)
  }
  override def setup(): Unit = {
    for (i <- 0 until plateCount) {
      val x = random(width)
      val y = random(height)
      val color = plateColors(i)
      plates = plates :+ Plate(x, y, plateSpeed, color, plateSize)
    }
  }
  override def draw(): Unit = {
    background(255)
    stroke(0)
    fill(255)
    for (plate <- plates) {
      plate.move()
      plate.collide(plates)
      plate.display()
    }
  }
  case class Plate(x: Float, y: Float, speed: Float, color: Int, size: Int) {
    var velocity = PVector.random2D().mult(speed)
    def move(): Unit = {
      x += velocity.x
      y += velocity.y
    }
    def collide(otherPlates: Seq[Plate]): Unit = {
      for (otherPlate <- otherPlates if otherPlate != this) {
        val distance = dist(x, y, otherPlate.x, otherPlate.y)
        val minDistance = size / 2 + otherPlate.size / 2
        if (distance < minDistance) {
          val angle = atan2(y - otherPlate.y, x - otherPlate.x)
          val overlap = minDistance - distance
          val thisForce = PVector.fromAngle(angle).mult(overlap / 2)
          val otherForce = PVector.fromAngle(angle + PI).mult(overlap / 2)
          velocity.add(thisForce)
          otherPlate.velocity.add(otherForce)
        }
      }
    }
    def display(): Unit = {
      fill(color)
      ellipse(x, y, size, size)
    }
  }
}
```
This code creates a simulation of multiple tectonic plates moving around the Earth's surface, colliding with each other and causing earthquakes and volcanic eruptions. The `Plate` case class represents each tectonic plate, with its position, velocity, size, and color. The `move` method updates the plate's position based on its velocity, while the `collide` method checks for collisions with other plates and adjusts their velocities accordingly. The `display` method draws the plate as a colored circle on the screen.
