#include <Wt/WMenuItem.h>
using namespace Wt;
class MyApplication : public WApplication {
public:
  MyApplication(const WEnvironment& env) : WApplication(env) {
    // Create a container widget to hold the menu
    WContainerWidget* container = new WContainerWidget(root());
    // Create the menu widget
    WMenu* menu = new WMenu(container);
    menu->setStyleClass("nav-menu");
    // Add the menu items
    menu->addItem("Home", new WMenuItem("Home"));
    menu->addItem("About", new WMenuItem("About"));
    menu->addItem("Services", new WMenuItem("Services"));
    menu->addItem("Contact", new WMenuItem("Contact"));
