class Blockchain {
private:
    vector<Block> chain;
    int difficulty;
public:
    Blockchain(int difficulty) {
        this->difficulty = difficulty;
        Block genesis = createGenesisBlock();
        chain.push_back(genesis);
    }
    // Create the genesis block
    Block createGenesisBlock() {
        Block genesis;
        genesis.index = 0;
        genesis.timestamp = getCurrentTime();
        genesis.data = "Genesis Block";
        genesis.previousHash = "";
        genesis.nonce = 0;
        genesis.hash = calculateHash(genesis);
        return genesis;
    }
    // Create a new block
    Block createBlock(string data) {
        Block newBlock;
        newBlock.index = chain.size();
        newBlock.timestamp = getCurrentTime();
        newBlock.data = data;
        newBlock.previousHash = chain[chain.size() - 1].hash;
        newBlock.nonce = 0;
        newBlock.hash = mineBlock(newBlock);
        return newBlock;
    }
    // Get the latest block
    Block getLatestBlock() {
        return chain[chain.size() - 1];
    }
    // Add a block to the chain
    void addBlock(Block newBlock) {
        chain.push_back(newBlock);
    }
    // Check if the chain is valid
    bool isChainValid() {
        for (int i = 1; i < chain.size(); i++) {
            Block currentBlock = chain[i];
            Block previousBlock = chain[i - 1];
            if (currentBlock.hash != calculateHash(currentBlock)) {
                return false;
            }
            if (currentBlock.previousHash != previousBlock.hash) {
                return false;
            }
        }
        return true;
    }
    // Calculate the hash of a block
    string calculateHash(Block block) {
        stringstream ss;
        ss << block.index << block.timestamp << block.data << block.previousHash << block.nonce;
        string input = ss.str();
        unsigned char hash[SHA256_DIGEST_LENGTH];
        SHA256_CTX sha256;
        SHA256_Init(&sha256);
        SHA256_Update(&sha256, input.c_str(), input.length());
        SHA256_Final(hash, &sha256);
        stringstream ss2;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; i++) {
            ss2 << hex << (int)hash[i];
        }
        return ss2.str();
    }
    // Mine a block
    string mineBlock(Block block) {
        string target(difficulty, '0');
        while (block.hash.substr(0, difficulty) != target) {
            block.nonce++;
            block.hash = calculateHash(block);
        }
        return block.hash;
    }
