1. Pomodoro Technique: This technique involves working for 25 minutes and then taking a 5-minute break. After 4 work sessions, take a longer break of 15-20 minutes. Here's a sample code snippet for a timer that implements this technique:
```
var timer = Timer()
var count = 1500 // 25 minutes in seconds
func startTimer() {
    timer = Timer.scheduledTimer(timeInterval: 1, target: self, selector: #selector(updateTimer), userInfo: nil, repeats: true)
}
@objc func updateTimer() {
    if count > 0 {
        count -= 1
    } else {
        timer.invalidate()
        // Take a 5-minute break
        count = 300
        startTimer()
    }
}
```
