Sure! Natural selection is the process by which certain heritable traits become more or less common in a population over time, depending on whether they confer an advantage or disadvantage in a particular environment. This happens because individuals with advantageous traits are more likely to survive and reproduce, passing those traits on to their offspring.
To simulate natural selection in a Swift program, you could create a population of organisms with different phenotypes (i.e. observable traits) and simulate an environment with different selective pressures. Here's an example code that simulates a population of organisms with different colors (red, green, and blue) and a predator that targets red organisms:
```swift
class Organism {
    let color: String
    var fitness: Double

    init(color: String) {
        self.color = color
        self.fitness = 1.0
    }

    func reproduce() -> Organism {
        let offspring = Organism(color: self.color)
        offspring.fitness = self.fitness + Double.random(in: -0.1...0.1)
        return offspring
    }
}
class Environment {
    let predator: String

    init(predator: String) {
        self.predator = predator
    }

    func select(population: [Organism]) -> [Organism] {
        var newPopulation: [Organism] = []
        for organism in population {
            if organism.color == "red" {
                organism.fitness *= 0.5 // red organisms have lower fitness due to predator
            }
            newPopulation.append(organism.reproduce())
        }
        return newPopulation
    }
}
