                 1, 1, 1, 0, 1, 0, 1, 0, 0, 0), nrow = 10, ncol = 10, byrow = TRUE)
# Define the function to find the shortest path
find_shortest_path <- function(maze, start, end) {
  # Define the neighbors of a cell
  neighbors <- function(cell) {
    row <- cell[1]
    col <- cell[2]
    n <- list(c(row - 1, col), c(row + 1, col), c(row, col - 1), c(row, col + 1))
    n <- n[rowSums(n >= 1 & n <= nrow(maze) & ncol(maze)) == 2,]
    return(n)
  }

  # Initialize the queue and visited set
  queue <- list(start)
  visited <- matrix(FALSE, nrow = nrow(maze), ncol = ncol(maze))
  visited[start[1], start[2]] <- TRUE

  # Initialize the parent dictionary
  parent <- list()
  parent[toString(start)] <- NULL

  # BFS algorithm
  while(length(queue) > 0) {
    # Dequeue the next cell
    cell <- queue[[1]]
    queue <- queue[-1]

    # Check if we have reached the destination
    if(toString(cell) == toString(end)) {
      # Reconstruct the path
      path <- list(end)
      while(toString(path[[1]]) != toString(start)) {
        path <- list(parent[[toString(path[[1]])]], path)
      }
      return(path)
    }

    # Add the neighbors to the queue
    for(n in neighbors(cell)) {
      if(maze[n[1], n[2]] == 0 && !visited[n[1], n[2]]) {
        queue <- c(queue, list(n))
        visited[n[1], n[2]] <- TRUE
        parent[toString(n)] <- cell
      }
    }
  }

  # If the destination is unreachable
  return(NULL)
}
# Test the function
