```go
package main
import (
	"encoding/json"
	"net/http"
)
type Vegetable struct {
	Name  string `json:"name"`
	Color string `json:"color"`
	Taste string `json:"taste"`
}
func main() {
	vegetables := []Vegetable{
		{Name: "Carrots", Color: "Orange", Taste: "Crunchy, sweet"},
		{Name: "Broccoli", Color: "Green", Taste: "Crunchy, bitter"},
		{Name: "Cauliflower", Color: "White", Taste: "Crispy, mild"},
		{Name: "Zucchini", Color: "Green", Taste: "Tender, subtle"},
		{Name: "Mushrooms", Color: "Brown", Taste: "Earthy, meaty"},
		{Name: "Onions", Color: "Yellow", Taste: "Sweet, pungent"},
	}
	http.HandleFunc("/vegetables", func(w http.ResponseWriter, r *http.Request) {
		jsonData, err := json.Marshal(vegetables)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Write(jsonData)
	})
	http.ListenAndServe(":8080", nil)
}
