```csharp
using Microsoft.ML;
using Microsoft.ML.Data;
using System;
namespace LinearRegressionExample
{
    class Program
    {
        static void Main(string[] args)
        {
            // Create a new MLContext
            var context = new MLContext();
            // Define the data schema
            var schema = context.Data.SchemaDefinition.Create(typeof(DataPoint));
            // Load the training data
            var data = context.Data.LoadFromTextFile<DataPoint>("data.csv", schema: schema, hasHeader: true, separatorChar: ',');
            // Split the data into training and testing sets
            var (trainData, testData) = context.Data.TrainTestSplit(data, testFraction: 0.2);
            // Define the pipeline
            var pipeline = context.Transforms.Concatenate("Features", nameof(DataPoint.X))
                .Append(context.Transforms.NormalizeMinMax("Features"))
                .Append(context.Transforms.NormalizeMeanVariance("Features"))
                .Append(context.Transforms.Concatenate("Features", nameof(DataPoint.X), "Features"))
                .Append(context.Transforms.Concatenate("Label", nameof(DataPoint.Y)))
                .Append(context.Transforms.NormalizeMinMax("Label"))
                .Append(context.Transforms.NormalizeMeanVariance("Label"))
                .Append(context.Transforms.Concatenate("Label", nameof(DataPoint.Y), "Label"))
                .Append(context.Regression.Trainers.Sdca());
            // Train the model
            var model = pipeline.Fit(trainData);
            // Evaluate the model on the test data
            var predictions = model.Transform(testData);
            var metrics = context.Regression.Evaluate(predictions);
            Console.WriteLine($"R^2: {metrics.RSquared}");
            // Make a prediction on new data
            var predictionEngine = context.Model.CreatePredictionEngine<DataPoint, Prediction>(model);
