This is a classic problem in computer science called "sorting a list with minimal information". Here's one way to solve it using a variation of the merge sort algorithm:
1. Divide the bag of numbers into pairs of two.
2. Compare the two numbers in each pair and swap them if they are out of order.
3. Now we have a bag of sorted pairs. Merge these pairs by comparing the first number in each pair and putting the smaller one in a new bag. Keep doing this until all pairs have been merged into a single sorted bag.
4. Repeat steps 1-3 on the sorted bag until the bag is completely sorted.
Here's how the algorithm would look in code:
```
function mergeSortWithMinimalInfo(bag) {
  if (bag.length <= 1) {
    return bag;
  }
  const pairs = [];
  for (let i = 0; i < bag.length; i += 2) {
    const pair = [bag[i]];
    if (bag[i + 1] !== undefined) {
      pair.push(bag[i + 1]);
    }
    pairs.push(pair);
  }
  const sortedPairs = pairs.map(pair => {
    if (pair.length === 1) {
      return pair;
    }
    if (pair[0] > pair[1]) {
      return [pair[1], pair[0]];
    }
    return pair;
  });
  const mergedBag = [];
  for (let i = 0; i < sortedPairs.length; i += 2) {
    const pair1 = sortedPairs[i];
    const pair2 = sortedPairs[i + 1] || [];
    const mergedPair = [];
    let p1 = 0;
    let p2 = 0;
    while (p1 < pair1.length || p2 < pair2.length) {
      if (pair1[p1] === undefined) {
        mergedPair.push(pair2[p2]);
        p2++;
      } else if (pair2[p2] === undefined) {
        mergedPair.push(pair1[p1]);
        p1++;
      } else if (pair1[p1] < pair2[p2]) {
        mergedPair.push(pair1[p1]);
        p1++;
      } else {
        mergedPair.push(pair2[p2]);
        p2++;
      }
    }
    mergedBag.push(mergedPair);
  }
  return mergeSortWithMinimalInfo(mergedBag.flat());
}
```
This algorithm has a time complexity of O(n log n), which is the same as many other sorting algorithms. However, it requires less memory than some other algorithms because it only ever needs to store pairs of numbers, rather than the whole bag.

