<?php
// Function to check if two numbers share any common factors
function hasCommonFactors($a, $b) {
    for ($i = 2; $i <= min($a, $b); $i++) {
        if ($a % $i == 0 && $b % $i == 0) {
            return true;
        }
    }
    return false;
}
// Function to generate a random permutation of 25 numbers
function generatePermutation() {
    $numbers = range(1, 25);
    shuffle($numbers);
    return $numbers;
}
// Function to check if a given number can be placed in a specific cell of the grid
function isValid($grid, $row, $col, $number) {
    // Check if the number has already been used in the grid
    if (in_array($number, $grid)) {
        return false;
    }
    // Check if the number shares any common factors with its adjacent cells
    for ($i = $row-1; $i <= $row+1; $i++) {
        for ($j = $col-1; $j <= $col+1; $j++) {
            if ($i >= 0 && $i < 5 && $j >= 0 && $j < 5 && $grid[$i*5+$j] != 0 && hasCommonFactors($number, $grid[$i*5+$j])) {
                return false;
            }
        }
    }
    return true;
}
// Function to fill the grid recursively
function fillGrid(&$grid, $row, $col, $numbers) {
    // Base case: if all cells have been filled, return true
    if ($row == 5) {
        return true;
    }
    // If the current cell is already filled, move to the next cell
    if ($grid[$row*5+$col] != 0) {
        if ($col == 4) {
            return fillGrid($grid, $row+1, 0, $numbers);
        } else {
            return fillGrid($grid, $row, $col+1, $numbers);
        }
    }
    // Try each number in the current cell until a valid one is found
    for ($i = 0; $i < count($numbers); $i++) {
        if (isValid($grid, $row, $col, $numbers[$i])) {
            $grid[$row*5+$col] = $numbers[$i];
            if ($col == 4) {
                $nextRow = $row + 1;
                $nextCol = 0;
            } else {
                $nextRow = $row;
                $nextCol = $col + 1;
            }
            // Recursively fill the rest of the grid
            if (fillGrid($grid, $nextRow, $nextCol, $numbers)) {
                return true;
            }
            $grid[$row*5+$col] = 0;
        }
    }
    return false;
}
// Generate a random permutation of 25 numbers
$numbers = generatePermutation();
// Create an empty grid
$grid = array_fill(0, 25, 0);
// Fill the grid recursively
fillGrid($grid, 0, 0, $numbers);
// Print the grid
for ($i = 0; $i < 5; $i++) {
    for ($j = 0; $j < 5; $j++) {
        echo $grid[$i*5+$j] . " ";
    }
    echo "<br>";
}
?>
```
