import re
def get_gerund(word):
    if word.endswith('ie'):
        return word[:-2] + 'ying'
    elif word.endswith('e'):
        return word[:-1] + 'ing'
    elif re.match(r'[aeiou][^aeiouwxy]$', word):
        return word + word[-1] + 'ing'
    else:
        return word + 'ing'
def replace_verb_with_gerund(sentence):
    words = sentence.split()
    for i, word in enumerate(words):
        if i == 0:
            continue
        if word.endswith('.') or word.endswith('!') or word.endswith('?'):
            word = word[:-1]
        if word == 'is' or word == 'are' or word == 'am' or word == 'was' or word == 'were':
            words[i] = get_gerund(words[i-1])
    return ' '.join(words)
while True:
    sentence = input('Please enter a sentence: ')
    if sentence == '':
        break
    if not re.match(r'^[A-Z][^\.?!]*[\.?!]$', sentence):
        print('Invalid sentence. Please try again.')
        continue
    if not any(word in sentence for word in ['is', 'are', 'am', 'was', 'were']):
        print('No verb to replace. Please try again.')
        continue
    new_sentence = replace_verb_with_gerund(sentence)
    print('New sentence:', new_sentence)
```
