        {Down, 0, 0, "GOLANG"},
        {Across, 0, 2, "CODE"},
        {Down, 2, 0, "VARIABLE"},
        {Across, 2, 3, "FUNC"},
        {Down, 3, 2, "STRUCT"},
    }
    // Fill the grid with words
    for _, word := range words {
        for i, r := range word.Text {
