func calculatePValue(drugData: [Double], placeboData: [Double]) -> Double {
    let drugStats = calculateStatistics(data: drugData)
    let placeboStats = calculateStatistics(data: placeboData)
    let pooledVariance = ((drugData.count - 1) * pow(drugStats.stdDev, 2) + (placeboData.count - 1) * pow(placeboStats.stdDev, 2)) / Double(drugData.count + placeboData.count - 2)
    let tValue = (drugStats.mean - placeboStats.mean) / sqrt(pooledVariance * (1/Double(drugData.count) + 1/Double(placeboData.count)))
    let degreesOfFreedom = drugData.count + placeboData.count - 2
    let pValue = 1 - tCDF(tValue: tValue, degreesOfFreedom: degreesOfFreedom)
    return pValue
}
// Helper function to calculate the t-distribution cumulative distribution function
func tCDF(tValue: Double, degreesOfFreedom: Int) -> Double {
    let tDist = StudentTDistribution(degreesOfFreedom: degreesOfFreedom)
    return tDist.cumulativeProbability(x: tValue)
