% Simulation of hot-air balloon flight
% Constants
g = 9.81;           % Acceleration due to gravity (m/s^2)
R = 287;            % Gas constant for air (J/kg.K)
rho_0 = 1.225;      % Density of air at sea level (kg/m^3)
T_0 = 288.15;       % Temperature at sea level (K)
P_0 = 101325;       % Pressure at sea level (Pa)
A = pi*(3.5/2)^2;   % Cross-sectional area of balloon (m^2)
m_g = 100;          % Mass of gas in balloon (kg)
m_b = 500;          % Mass of balloon and payload (kg)
Cd = 0.5;           % Drag coefficient
V_w = [10; 0; 0];   % Wind velocity (m/s)
% Initial conditions
h0 = 0;             % Initial altitude (m)
v0 = 0;             % Initial velocity (m/s)
T0 = T_0;           % Initial temperature (K)
P0 = P_0;           % Initial pressure (Pa)
% Simulation parameters
tspan = [0 6000];   % Simulation time (s)
options = odeset('RelTol',1e-6,'AbsTol',1e-6);
% Function for calculating air density
function rho = air_density(h,T,P)
    rho = P/(R*T);
end
% Function for calculating buoyancy force
function F_b = buoyancy_force(rho_g,rho_a,V_g)
    F_b = (rho_g - rho_a)*V_g*g;
end
% Function for calculating drag force
function F_d = drag_force(rho_a,v)
    F_d = 0.5*rho_a*Cd*A*v^2;
end
% Function for calculating temperature and pressure
function [dT,dP] = temp_pressure(h,T,P)
    dT = -g*T/(R*h);
    dP = -rho_0*g*T/(R*h)*((1+(g*h)/(R*T_0)))^(1/0.0065);
end
% Function for calculating velocity and altitude
function [dh,dv] = velocity_altitude(t,y)
    h = y(1);
    v = y(2);
    T = y(3);
    P = y(4);

    % Calculate air density
    rho_a = air_density(h,T,P);

    % Calculate volume of balloon
    V_b = (m_g*R*T)/(P*m_b);

    % Calculate volume of displaced air
    V_g = V_b - (m_g/m_b)*V_b;

    % Calculate density of displaced air
    rho_g = P/(R*T);

    % Calculate buoyancy force
    F_b = buoyancy_force(rho_g,rho_a,V_g);

    % Calculate drag force
    F_d = drag_force(rho_a,v-V_w(1));

    % Calculate total force
    F = F_b - F_d - m_b*g;

    % Calculate temperature and pressure
    [dT,dP] = temp_pressure(h,T,P);

    % Calculate acceleration
    a = F/m_b;

    % Calculate velocity and altitude
    dv = a;
    dh = v;
end
% Solve differential equations
y0 = [h0; v0; T0; P0];
[t,y] = ode45(@velocity_altitude,tspan,y0,options);
