		tweetEngagement["favorites"] += tweet.FavoriteCount
		// Analyze tweet sentiment
		if analyzeSentiment(tweet.Text) == "positive" {
			tweetSentiment["positive"]++
		} else if analyzeSentiment(tweet.Text) == "negative" {
			tweetSentiment["negative"]++
		} else {
			tweetSentiment["neutral"]++
		}
	}
	// Print results
	fmt.Printf("Tweet types: %v\n", tweetTypes)
	fmt.Printf("Engagement: %v\n", tweetEngagement)
	fmt.Printf("Sentiment: %v\n", tweetSentiment)
}
// Analyze tweet sentiment using the TextBlob API
func analyzeSentiment(text string) string {
	// Set up API endpoint
	apiUrl := "http://textblob-api.herokuapp.com/api/sentiment/"
	resource := fmt.Sprintf("%s", url.QueryEscape(text))
	u, _ := url.ParseRequestURI(apiUrl)
	u.Path = resource
	urlStr := u.String()
	// Make API request
	client := &http.Client{}
	r, err := http.NewRequest("GET", urlStr, nil)
	if err != nil {
		log.Fatal(err)
	}
	r.Header.Add("Content-Type", "application/json")
	r.Header.Add("Accept", "application/json")
	resp, err := client.Do(r)
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()
	// Parse API response
	var result map[string]interface{}
	err = json.NewDecoder(resp.Body).Decode(&result)
	if err != nil {
		log.Fatal(err)
	}
	// Return sentiment label
	if polarity, ok := result["polarity"].(float64); ok {
		if polarity > 0 {
			return "positive"
		} else if polarity < 0 {
			return "negative"
		}
	}
	return "neutral"
}
