    std::vector<sf::CircleShape> stars;
    for (int i = 0; i < 100; i++) {
        sf::CircleShape star(2);
        star.setPosition(dis(gen), dis(gen));
        star.setFillColor(sf::Color(255, 255, 255, 200));
        stars.push_back(star);
    }
    // Create the buildings
    std::vector<sf::RectangleShape> buildings;
    for (int i = 0; i < 10; i++) {
        sf::RectangleShape building(sf::Vector2f(80, dis(gen) + 200));
        building.setPosition(i * 80, 400 - building.getSize().y);
        building.setFillColor(sf::Color(100, 100, 100));
        buildings.push_back(building);
    }
    // Create the meteors
    std::vector<sf::CircleShape> meteors;
    for (int i = 0; i < 10; i++) {
